  int cur_ans = n;
  for (int i = m; i >= 0; i--) {
    if (!del[i]) {
      int u = edges[i].first, v = edges[i].second;
      if (deg[u] == k) {
        q.push(u);
      }
      if (deg[v] == k) {
        q.push(v);
