void f(int k, int iteration) {
  while (!good.empty() && good.begin()->first < k) {
    int v = good.begin()->second;
    for (auto j : g[v]) {
      int i = j.first;
      int it = j.second;
      if (iteration <= it) continue;
      if (in_good[i]) {
        good.erase({deg[i], i});
