        boolean[] was = new boolean[n];
        int head = 0;
        int tail = 0;
        for (int i = 0; i < n; i++) {
            if (edges[i].size() < k) {
                q[tail++] = i;
                was[i] = true;
            }
        }

        int[] ans = new int[m];

