void remove(long long r) {
  st.erase(r);
  for (long long i = 0; i < adj[r].size(); i++) {
    long long c = adj[r][i];
    if (st.find(c) == st.end()) continue;
    if (edges.find(make_pair(r, c)) == edges.end()) continue;
    edges.erase(make_pair(r, c));
    edges.erase(make_pair(c, r));
    deg[c]--;
    if (deg[c] < k) remove(c);
  }
}
