bool vis[N];
queue<int> Q;
set<int> G[N];
vector<int> E[N];
int a[N], b[N], ans[N], sum;
void solve() {
  while (!Q.empty()) {
    int u = Q.front();
    Q.pop();
    for (auto v : G[u]) {
      G[v].erase(u);
      if (!vis[v] && G[v].size() < k) {
        sum--;
        vis[v] = 1;
        Q.push(v);
      }
    }
  }
}
int main() {
  scanf("%d%d%d", &n, &m, &k);
  sum = n;
