  }
  for (int i = 0; i < n; ++i) {
    std::stack<int> rejected;
    rejected.push(i);
    while (!rejected.empty()) {
      int index = rejected.top();
      rejected.pop();
      if (!(selected[index] == 1 && friends_going[index] < k)) {
        continue;
      }
      selected[index] = 0;
      --total;
      for (int j : edges[index]) {
        --friends_going[j];
        rejected.push(j);
      }
    }
  }
  int answer[m];
  answer[m - 1] = total;
  for (int i = m - 2; i >= 0; --i) {
    int first = friends[i + 1][0], second = friends[i + 1][1];
    edges[first].pop_back();
    edges[second].pop_back();
    if (selected[second] == 1) {
      --friends_going[first];
    }
    if (selected[first]) {
      --friends_going[second];
    }
    std::stack<int> rejected;
    rejected.push(first);
    rejected.push(second);
    while (!rejected.empty()) {
      int index = rejected.top();
      rejected.pop();
      if (!(selected[index] == 1 && friends_going[index] < k)) {
        continue;
      }
      selected[index] = 0;
      --total;
      for (int j : edges[index]) {
        --friends_going[j];
        rejected.push(j);
      }
    }
    answer[i] = total;
  }
  for (int i = 0; i < m; i++) {
    printf("%d\n", answer[i]);
  }
