		for (int i = 0; i < m; i++) {
			from[i] = scn.nextInt() - 1;
			to[i] = scn.nextInt() - 1;
			w[i] = i;
		}

		int[][][] g = packWU(n, from, to, w);
		int[] deg = new int[n], q = new int[n];
		int qp = 0, st = 0;

		for (int i = 0; i < n; i++) {
			deg[i] = g[i].length;
			if (deg[i] < k) {
				q[qp++] = i;
			}
		}

		boolean[] step = new boolean[m];
		int[] ans = new int[m];
		for (int i = m - 1; i >= 0; i--) {
			while (st < qp) {
				for (int[] v : g[q[st]]) {
					if (!step[v[1]]) {
						step[v[1]] = true;
						if (deg[v[0]] == k) {
							q[qp++] = v[0];
						}
						deg[v[0]]--;
						deg[q[st]]--;
					}
				}
				st++;
			}
			ans[i] = n - qp;

			if (!step[i]) {
				step[i] = true;
				if (deg[to[i]] == k) {
					q[qp++] = to[i];
				}
				if (deg[from[i]] == k) {
					q[qp++] = from[i];
				}
				deg[to[i]]--;
				deg[from[i]]--;
			}
		}

		for (int i = 0; i < m; i++) {
			out.println(ans[i]);
		}
	}

	int[][][] packWU(int n, int[] from, int[] to, int[] w) {
		n++;
		int[][][] g = new int[n][][];
		int[] p = new int[n];
		for (int f : from)
			p[f]++;
		for (int t : to)
			p[t]++;
		for (int i = 0; i < n; i++)
			g[i] = new int[p[i]][2];
		for (int i = 0; i < from.length; i++) {
			--p[from[i]];
			g[from[i]][p[from[i]]][0] = to[i];
			g[from[i]][p[from[i]]][1] = w[i];
			--p[to[i]];
			g[to[i]][p[to[i]]][0] = from[i];
			g[to[i]][p[to[i]]][1] = w[i];
		}
		return g;
	}

	void run() throws Exception {
		long time = System.currentTimeMillis();
		boolean oj = System.getProperty("ONLINE_JUDGE") != null;
		out = new PrintWriter(System.out);
		scn = new FastReader(oj);
		solve();
		out.flush();
		if (!oj) {
			System.out.println(Arrays.deepToString(new Object[] { System.currentTimeMillis() - time + " ms" }));
		}
	}

