void update() {
  while (!toRemove.empty()) {
    int r = toRemove.front();
    toRemove.pop();
    numOn--;
    for (auto next : f[r]) {
      f[next].erase(r);
      if (on[next] && ((int)(f[next]).size()) < k) {
        on[next] = 0;
        toRemove.push(next);
      }
    }
    f[r].clear();
  }
