    static class TaskE {
        int k;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            k = in.nextInt();

            LinkedList<Integer>[] adj = new LinkedList[n];

            IntPair[] degree = new IntPair[n];
            for (int i = 0; i < n; i++) {
                degree[i] = IntPair.newPair(0, i);
                adj[i] = new LinkedList<>();
            }


            int[] u = new int[m];
            int[] v = new int[m];

            for (int i = 0; i < m; ++i) {
                u[i] = in.nextInt() - 1;
                v[i] = in.nextInt() - 1;

                adj[u[i]].add(i);
                adj[v[i]].add(i);
                degree[u[i]].first++;
                degree[v[i]].first++;
            }

            TreeSet<IntPair> set = new TreeSet<>();
            for (int i = 0; i < n; i++) {
                set.add(degree[i]);
            }

            boolean[] alive = ArrayUtils.createArray(n, true);

            while (!set.isEmpty() && set.first().first < k) {
                IntPair pair = set.first();
                for (Iterator<Integer> it = adj[pair.second].iterator(); it.hasNext(); ) {
                    int edge = it.next();
                    int e = v[edge] == pair.second ? u[edge] : v[edge];
                    set.remove(degree[e]);
                    degree[e].first--;
                    set.add(degree[e]);
                    it.remove();
                }
                set.remove(pair);
                alive[pair.second] = false;
            }

            int[] result = new int[m];
            for (int i = m - 1; i >= 0; --i) {
                result[i] = set.size();
                if (alive[u[i]] && alive[v[i]]) {
                    set.remove(degree[u[i]]);
                    degree[u[i]].first--;
                    set.add(degree[u[i]]);

                    set.remove(degree[v[i]]);
                    degree[v[i]].first--;
                    set.add(degree[v[i]]);

                    while (!set.isEmpty() && set.first().first < k) {
                        IntPair pair = set.first();
//                    for (int e : graph.getEdgesFrom(pair.second)) if (alive[e] && !(e == u[i] && pair.second == v[i]) && !(e == v[i] && pair.second == u[i])) {
                        for (Iterator<Integer> it = adj[pair.second].iterator(); it.hasNext(); ) {
                            int edge = it.next();
                            it.remove();
                            if (edge < i) {
                                int e = v[edge] == pair.second ? u[edge] : v[edge];
                                if (!alive[e]) continue;
                                set.remove(degree[e]);
                                degree[e].first--;
                                set.add(degree[e]);
                            }
                        }
                        set.remove(pair);
                        alive[pair.second] = false;
                    }
                }
            }

            for (int e : result)
                out.println(e);
        }

