	static int left,ind;
	static boolean[] bad;
	static int[] deg;
	static ArrayList<edge>[] a;
	static int k;

	public static void go(int at) {
		bad[at]=true;
		ArrayDeque<Integer> q=new ArrayDeque<>();
		left--;
		q.offer(at);
		while(!q.isEmpty()) {
			int c=q.poll();
			for(edge nxt:a[c]) {
				if(nxt.id>=ind) continue;
				if(!bad[nxt.v]&&--deg[nxt.v]<k) {
					q.offer(nxt.v);
					bad[nxt.v]=true;
					left--;
				}
			}
		}
	}
