  q.push(start);
  while (!q.empty()) {
    int v = q.front();
    q.pop();
    assert(selected[v]);
    assert((int)g[v].size() < k);
    selected[v] = 0;
    res--;
    for (auto t : g[v]) {
      g[t].erase(v);
      if (selected[t] && (int)g[t].size() < k && !used[t]) {
        seen.push_back(t);
        used[t] = 1;
        q.push(t);
      }
    }
  }
  for (auto t : seen) {
    used[t] = 0;
  }
}
