int sum = 0;
queue<int> q;
void Top() {
  while (!q.empty()) {
    ++sum;
    int u = q.front();
    q.pop();
    ind[u] = 0;
    set<int>::iterator it;
    for (it = vec[u].begin(); it != vec[u].end();) {
      int v = *it;
      if (vis[v]) {
        it++;
        continue;
      }
      vec[u].erase(it++);
      vec[v].erase(u);
      ind[v]--;
      if (!vis[v] && ind[v] < K) {
        vis[v] = 1;
        q.push(v);
      }
    }
  }
}
