				if(!vis[pr.f] && !vis[pr.s]) {
//					pw.println("EDGE RUN");

					s.remove(new Pair(deg[pr.f], pr.f));
					s.remove(new Pair(deg[pr.s], pr.s));
					deg[pr.f]--;
					deg[pr.s]--;
					s.add(new Pair(deg[pr.f],pr.f));
					s.add(new Pair(deg[pr.s], pr.s));
