							Pair p = s.pollFirst();
							for(int e : adj[p.s]) {
								if(visited.contains(new Pair(p.s, e))) {
									continue;
								}
								if(vis[e] || ((p.s == pr.f && e == pr.s) || (p.s == pr.s && e == pr.f))) {
									continue;
								}
								s.remove(new Pair(deg[e], e));
