int n, m, k, cnt;
void deletev(int v) {
  if (deg[v] >= k || vis[v]) return;
  queue<int> q;
  q.push(v);
  vis[v] = 1;
  --cnt;
  while (!q.empty()) {
    int top = q.front();
    q.pop();
    for (auto& c : e[top]) {
      --deg[c];
      if (deg[c] < k && !vis[c]) {
        q.push(c);
        vis[c] = 1;
        --cnt;
      }
    }
  }
}
