    memset(to, (0), sizeof(to));
    memset(deg, (0), sizeof(deg));
    memset(vis, (0), sizeof(vis));
    memset(res, (0), sizeof(res));
    e->clear();
    for (int i = (0); i < (m); ++i) {
      cin >> from[i] >> to[i];
      --from[i], --to[i];
      ++deg[from[i]], ++deg[to[i]];
      e[from[i]].insert(to[i]);
      e[to[i]].insert(from[i]);
    }
    cnt = n;
    for (int i = (0); i < (n); ++i) {
      deletev(i);
    }
    res[m] = cnt;
