bool del[maxn];
using namespace std;
map<pair<int, int>, int> mp;
struct node {
  int v, next;
} edge[maxn];
int head[maxn], num = 0;
inline void add_edge(int u, int v) {
  edge[++num].v = v;
  edge[num].next = head[u];
  head[u] = num;
}
int ans;
int u[maxn], v[maxn];
int Ans[maxn];
queue<int> q;
void solve(int x) {
  if (d[x] >= k || del[x]) return;
  del[x] = 1;
  q.push(x);
  ans--;
  while (!q.empty()) {
    int U = q.front();
    q.pop();
    for (int i = head[U]; i; i = edge[i].next) {
      int V = edge[i].v;
      if (del[V]) continue;
      if (mp.count(make_pair(U, V)) == 0) d[V]--;
      if (d[V] < k) {
        del[V] = true;
        ans--;
        q.push(V);
      }
    }
  }
}
