bool inGraph[MAXN];
int ans[MAXN];
void update(int x) {
  if (!inGraph[x]) return;
  set<pair<int, int> >::iterator it = st.find(make_pair(deg[x], x));
  st.erase(it);
  deg[x]--;
  st.insert(make_pair(deg[x], x));
}
void fix() {
  while (!st.empty() && st.begin()->first < K) {
    int cur = st.begin()->second;
    st.erase(st.begin());
    inGraph[cur] = false;
    for (auto nxt : adj[cur]) {
      adj[nxt].erase(cur);
      update(nxt);
    }
    adj[cur].clear();
  }
}
