    deg[B[i]]++;
    adj[A[i]].insert(B[i]);
    adj[B[i]].insert(A[i]);
  }
  for (int i = 1; i <= N; i++) {
    st.insert(make_pair(deg[i], i));
    inGraph[i] = true;
  }
  for (int i = M - 1; i >= 0; i--) {
    fix();
    ans[i] = st.size();
