                if (degree[a] < k){
                    q.add(a);
                    s[a] = false;
                    size--;
                }
                if (degree[b] < k){
                    q.add(b);
                    s[b] = false;
                    size--;
                }
                while (!q.isEmpty()){
                    int v = q.poll();
                    for (Pair u : g[v]) {
                        if(u.b < i && s[u.a]) {
                            degree[u.a]--;
                            if (degree[u.a] < k) {
                                q.add(u.a);
                                s[u.a] = false;
                                size--;
                            }
                        }
                    }

                }
            }
        }
        for (int i = 0; i < m; i++) {
            System.out.println(ans[i]);
        }

    }
    static class Pair{
        int a;
        int b;

        public Pair(int a, int b) {
            this.a = a;
            this.b = b;
        }
    }
}
