        OutputWriter out = new OutputWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE {
        Set[] g;
        int[] deg;
        Set<Integer> s;
        int k;
        int n;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            n = in.nextInt();
            int m = in.nextInt();
            k = in.nextInt();

            g = new Set[n];

            for (int i = 0; i < n; i++) {
                g[i] = new HashSet();
            }

            deg = new int[n];

            List<edge> edges = new ArrayList<>();
            for (int i = 0; i < m; i++) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;
                edges.add(new edge(u, v));
                g[u].add(v);
                g[v].add(u);
                deg[u]++;
                deg[v]++;
            }


            s = new HashSet<>();

            List<vertex> vertices = new ArrayList<>();

            for (int i = 0; i < n; i++) {
                s.add(i);
                vertices.add(new vertex(i, deg[i]));
            }

            vertices.sort((v1, v2) -> v1.d - v2.d);

            int i = 0;
            for (i = 0; i < n; i++) {
                if (vertices.get(i).d < k) {
                    int u = vertices.get(i).u;
                    if (s.contains(u))
                        dfs(u, -1, -1);
                } else {
                    break;
                }
            }

            //out.println(s.size());
            List<Integer> ans = new ArrayList<>();
            ans.add(s.size());
            for (int j = m - 1; j > 0; j--) {
                edge ce = edges.get(j);
                g[ce.u].remove(ce.v);
                g[ce.v].remove(ce.u);
                if (s.contains(ce.u) && s.contains(ce.v)) {
//                ArrayDeque<Integer> q = new ArrayDeque<>();
//
//                q.addFirst(ce.u);
//                q.addLast(ce.v);
//
//                while (!q.isEmpty()) {
//                    int e = q.removeFirst();
//
//                    deg[e]--;
//
//                    if (deg[e] < k) {
//                        s.remove(e);
//                        for (int v : (Set<Integer>) g[e]) {
//                            if (s.contains(v)) {
//                                q.addLast(v);
//                            }
//                        }
//                    }
//                }

                    dfs(ce.u, ce.v, ce.u);
                    if (s.contains(ce.v))
                        dfs(ce.v, ce.u, ce.v);
                }

                ans.add(s.size());
                //out.println(s.size());
            }

            for (int j = ans.size() - 1; j >= 0; j--) {
                out.println(ans.get(j));
            }
        }

        void dfs(int u, int ov, int ou) {
            deg[u]--;

            if (deg[u] >= k) {
                return;
            }

            s.remove(u);

            for (int v : (Set<Integer>) g[u]) {
                if (s.contains(v)) {
                    dfs(v, ov, ou);
                }
            }


        }

        class edge {
            int u;
