using namespace std;
void del(int edge, vector<set<int>>& g, map<int, int>& degr, int k) {
  degr.erase(degr.find(edge));
  for (auto neigh : g[edge]) {
    g[neigh].erase(edge);
    auto it = degr.find(neigh);
    if (it != degr.end()) {
      if (--degr[neigh] < k) {
        del(neigh, g, degr, k);
      }
    }
  }
  g[edge].clear();
}
int main() {
