    g[a].insert(b);
    g[b].insert(a);
    edges.push_back({a, b});
    degr[a]++;
    degr[b]++;
  }
  for (int i = 0; i < n; i++) {
    if (degr.find(i) != degr.end() && degr[i] < k) {
      del(i, g, degr, k);
    }
  }
