      for (int i = m - 1; i >= 0; --i) {
        res[i] = cur;
        int x = edges.get(i).first, y = edges.get(i).second;
        --T;
        if (alive[x]) {
          --deg[y];
        }
        if (alive[y]) {
          --deg[x];
        }
        update(x);
        update(y);
      }
      for (int i = 0; i < m; ++i) {
        out.printLine(res[i]);
      }
    }

    private void update(int x) {
      if (!alive[x]) {
        return;
      }
      int ql = 0, qr = 0;
      q[ql++] = x;
      while (ql > qr) {
        x = q[qr++];
        if (!alive[x]) {
          continue;
        }
        Assert.assertTrue(g[x].size() >= deg[x]);
        if (deg[x] >= k) {
          while (g[x].get(g[x].size() - 1).second > T) {
            g[x].remove(g[x].size() - 1);
          }
        } else {
          for (ii e : g[x]) {
            int y = e.first;
            if (alive[y] && deg[y] >= k && e.second <= T) {
              --deg[y];
              if (deg[y] < k) {
                q[ql++] = y;
              }
            }
          }
          g[x].clear();
          deg[x] = 0;
          alive[x] = false;
          --cur;
        }
      }
    }

  }

