        }
        @Override
        public int compareTo(Pair o) {
            if(this.first == o.first){
                if(this.second == o.second){
                    return 0;
                }else{
                    return this.second > o.second ? 1 : -1;
                }
            }else{
                return this.first > o.first ? 1 : -1;
            }
        }
    }

