class Graph(object):
  def __init__(self, n):
    self.n = n
    self.adj = [set() for i in xrange(n+1)]
    self.rank = [0 for i in xrange(n+1)]
    self.color = [True for i in xrange(n+1)]

  def add_edge(self, a, b):
    self.adj[a].add(b)
    self.adj[b].add(a)
    self.rank[a] += 1
    self.rank[b] += 1

  def remove_edge(self, a, b):
    if b in self.adj[a]:
      self.rank[a] -= 1
      self.adj[a].remove(b)
    if a in self.adj[b]:
      self.adj[b].remove(a)
      self.rank[b] -= 1


