void bfs(int u, int time) {
  queue<int> qu;
  done[u] = 1;
  cur--;
  qu.push(u);
  int v;
  while (!qu.empty()) {
    u = qu.front();
    qu.pop();
    for (int i = 0; i < ve[u].size(); i++) {
      v = ve[u][i].first;
      if (done[v]) continue;
      if (ve[u][i].second > time) continue;
      deg[u]--;
      deg[v]--;
      if (deg[v] < k) {
        cur--;
        done[v] = 1;
        qu.push(v);
      }
    }
  }
}
