  S.erase(ind(x, de[x]));
  de[x]--;
  S.insert(ind(x, de[x]));
}
void dele(int x) {
  S.erase(ind(x, de[x]));
  for (auto y : pa[x])
    if (!ex[y] && de[fd(y, x)] >= k) erase(fd(y, x));
}
