      q.push(i);
      vis[i] = 1;
    }
  }
  int cur = n - q.size();
  set<pair<int, int> > cnt;
  while (!q.empty()) {
    auto x = q.front();
    q.pop();
    for (auto& it : G[x]) {
      auto node = minmax(x, it);
      if (cnt.find(node) == cnt.end()) {
        cnt.insert(node);
        if (!vis[it] && --in[it] < k) {
