	static int bfs(int id){
		int res =0;
		esize[u[id]]--;esize[v[id]]--;
		used[id]=true;
		Deque<Integer> que = new ArrayDeque<>();
		if(esize[u[id]]<k){
			que.add(u[id]);
			stay[u[id]]=true;
			++res;
		}
		if(esize[v[id]]<k){
			que.add(v[id]);
			stay[v[id]]=true;
			++res;
		}
		while(!que.isEmpty()){
			int p = que.poll();
			esize[p]=0;
			for(Edge e: edges[p])if(!used[e.id] && !stay[e.to]){
				used[e.id]=true;
				esize[e.to]--;
				if(esize[e.to]<k){
					que.add(e.to);stay[e.to]=true;
					++res;
				}
			}
		}
		return res;
	}

