		for(int i=0;i<n;++i)esize[i]=edges[i].size();
		stay = new boolean[n];
		Deque<Integer> que = new ArrayDeque<>();
		for(int i=0;i<n;++i)if(esize[i]<k){
			que.add(i);
			stay[i]=true;
			--remain;
		}

		while(!que.isEmpty()){
			int p = que.poll();
			esize[p]=0;
			for(Edge e: edges[p])if(!used[e.id] && !stay[e.to]){
				esize[e.to]--;
				used[e.id]=true;
				if(esize[e.to]<k){
