    {

        int x,y;

        Pair(int x, int y){
            this.x = x;
            this.y = y;
        }

	public int compareTo(Pair o)
        {
            if(this.x == o.x)
                return -Integer.compare(this.y, o.y);
            return Integer.compare(this.x, o.x);
	}

