void reduce() {
  if (in.empty()) return;
  int x = *in.begin();
  if (adj[x].size() >= K) return;
  in.erase(x);
  for (auto it : adj[x])
    if (in.count(it)) {
      in.erase(it);
      adj[it].erase(x);
      in.insert(it);
    }
  reduce();
}
