        for(int i = 0; i < n; ++i)
            adj[i] = new HashSet<>();

        for(int i = 0; i < m; ++i) {
            int u = edge[i].u;
            int v = edge[i].v;

            adj[u].add(v);
            adj[v].add(u);
        }

        PriorityQueue<Pair> queue = new PriorityQueue<>(new Comparator<Pair>() {
            public int compare(Pair p1, Pair p2) {
                if(p1.deg < p2.deg)
                    return -1;
                if(p1.deg > p2.deg)
                    return 1;
                return 0;
            }
        });

