        for(int i = 0; i < n; ++i)
            queue.add(new Pair(i, deg[i]));

        int curDeg[] = new int[n];
        for(int i = 0; i < n; ++i)
            curDeg[i] = deg[i];

        while(!queue.isEmpty()) {
            Pair cur = queue.poll();
            int ind = cur.ind;
            if(vis[ind] == 1)
                continue;

            int cdeg = cur.deg;
            vis[ind] = 1;

            if(cdeg >= k) {
                selected[ind] = 1;
                cans++;
                continue;
            }

            for(int j : adj[ind]) {
                if(vis[j] == 0) {
                    curDeg[j]--;
                    queue.add(new Pair(j, curDeg[j]));
                }
            }
        }

