public class E {
    static LinkedList<Pair>[] g;
    static int k;
    static Set<Integer> s;
    static int[] degree;
    static Queue<Integer> q = new LinkedList<>();

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(reader.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        k = Integer.parseInt(st.nextToken());
        s = new HashSet<>(2*m);
        g = new LinkedList[n];
        degree = new int[n];
        int[][] f = new int[m][2];
        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(reader.readLine());
            int a = Integer.parseInt(st.nextToken())-1;
            int b = Integer.parseInt(st.nextToken())-1;
            if (g[a] == null) {
                g[a] = new LinkedList<>();
            }
            if (g[b] == null) {
                g[b] = new LinkedList<>();
            }
            g[a].add(new Pair(b,i));
            g[b].add(new Pair(a,i));
            degree[a]++;degree[b]++;
            f[i][0] = a;
            f[i][1] = b;
        }
        for (int i = 0; i < n; i++) {
            if(degree[i]>0){
                if(degree[i]>=k){
                    s.add(i);
                }else{
                    q.add(i);
                }
            }
        }

        while (!q.isEmpty()){
            int v = q.poll();
            for (Pair u : g[v]) {
                if(s.contains(u.a)) {
                    degree[u.a]--;
                    if (degree[u.a] < k) {
                        q.add(u.a);
                        s.remove(u.a);
                    }
                }
            }
        }
        int[] ans = new int[m];
        for (int i = m-1; i >=0; i--) {
            ans[i] = s.size();
            int a = f[i][0];
            int b = f[i][1];
            if(s.contains(a) && s.contains(b)) {
                degree[a]--;degree[b]--;
                if (degree[a] < k){
                    q.add(a);
                    s.remove(a);
                }
                if (degree[b] < k){
                    q.add(b);
                    s.remove(b);
                }
                while (!q.isEmpty()){
                    int v = q.poll();
                    for (Pair u : g[v]) {
                        if(u.b < i && s.contains(u.a)) {
                            degree[u.a]--;
                            if (degree[u.a] < k) {
                                q.add(u.a);
                                s.remove(u.a);
                            }
                        }
                    }

                }
            }
        }
        for (int i = 0; i < m; i++) {
            System.out.println(ans[i]);
        }

    }
    static class Pair{
        int a;
        int b;

        public Pair(int a, int b) {
            this.a = a;
            this.b = b;
        }
    }
}
