public class Main implements Runnable {
	FastReader scn;
	PrintWriter out;
	String INPUT = "";

	void solve() {
		int n = scn.nextInt(), m = scn.nextInt(), k = scn.nextInt();
		int[] from = new int[m], to = new int[m], w = new int[m];
		for(int i = m - 1; i >= 0; i--) {
			from[i] = scn.nextInt() - 1;
			to[i] = scn.nextInt() - 1;
			w[i] = i;
		}

		int[][][] g = packWU(n, from, to, w);
		int[] deg = new int[n], q = new int[n];
		int end = 0, start = 0;
		for(int i = 0; i < n; i++) {
			deg[i] = g[i].length;
			if(deg[i] < k) {
				q[end++] = i;
			}
		}

		boolean[] done = new boolean[m];
		int[] ans = new int[m];

		for(int i = 0; i < m; i++) {
			while(start < end) {
				for(int[] v : g[q[start]]) {
					if(!done[v[1]]) {
						done[v[1]] = true;
						if(deg[v[0]] == k) {
							q[end++] = v[0];
						}
						deg[v[0]]--;
						deg[q[start]]--;
					}
				}
				start++;
			}

			ans[m - i - 1] = n - end;
			if(!done[i]) {
				done[i] = true;
				if(deg[from[i]] == k) {
					q[end++] = from[i];
				}
				if(deg[to[i]] == k) {
					q[end++] = to[i];
				}
				deg[from[i]]--;
				deg[to[i]]--;
			}
		}

		for(int a : ans) {
			out.println(a);
		}
	}

	int[][][] packWU(int n, int[] from, int[] to, int[] w) {
		int[][][] g = new int[n][][];
		int[] p = new int[n];
		for (int f : from)
			p[f]++;
		for (int t : to)
			p[t]++;
		for (int i = 0; i < n; i++)
			g[i] = new int[p[i]][2];
		for (int i = 0; i < from.length; i++) {
			--p[from[i]];
			g[from[i]][p[from[i]]][0] = to[i];
			g[from[i]][p[from[i]]][1] = w[i];
			--p[to[i]];
			g[to[i]][p[to[i]]][0] = from[i];
			g[to[i]][p[to[i]]][1] = w[i];
		}
		return g;
	}

	public void run() {
		long time = System.currentTimeMillis();
		boolean oj = System.getProperty("ONLINE_JUDGE") != null;
		out = new PrintWriter(System.out);
		scn = new FastReader(oj);
		solve();
		out.flush();
		if (!oj) {
			System.out.println(Arrays.deepToString(new Object[] { System.currentTimeMillis() - time + " ms" }));
		}
	}

