            graph[p1].add(p2);
            graph[p2].add(p1);
            size[p1]++;
            nEdges[p1]++;
            size[p2]++;
            nEdges[p2]++;
            edges.push(new Pair(p1, p2));
        }
        for(int i = 1; i < n+1; i++) {
            if (size[i] < k) {
                q.offer(i);
                size[i] = 0;
            }
        }
        while(!edges.isEmpty()) {
            while(!q.isEmpty()) {
                int curRem = q.poll();
                curSize--;
                for(int i = 0; i < nEdges[curRem]; i++) {
                    int node = graph[curRem].get(i);
                    size[node]--;
                    if (size[node] == k-1) {
                        q.add(node);
                        //size[node] = 0;
                    }
                }
            }
            out.push(curSize);
            Pair edge = edges.pop();
            int node1 = edge.a;
            int node2 = edge.b;
            nEdges[node1]--;
            nEdges[node2]--;
            //size[node1]--;
            //size[node2]--;
            boolean temp = size[node1] >= k;
            if (size[node2] >= k) {
                size[node1]--;
                if(size[node1] == k-1) {q.add(node1);}
            }
            if (temp) {
                size[node2]--;
                if(size[node2] == k-1) {q.add(node2);}
            }

        }
        while(!out.isEmpty()) {
            sb.append(out.pop());
            sb.append('\n');
