void add(int x, int y) {
  e[++en].u = x, e[en].v = y, e[en].nxt = head[x];
  if (!head[x]) e[head[x]].pre = en;
  head[x] = en;
}
int ans[N], cnt = 0;
void work() {
  while (!q.empty()) {
    int x = q.front();
    q.pop();
    if (!in[x]) continue;
    --cnt;
    in[x] = 0;
    for (int i = head[x]; i; i = e[i].nxt) {
      int y = e[i].v;
      e[i ^ 1].fg = e[i].fg = 1;
      if (--d[y] < k) q.push(y);
    }
  }
}
void delta(int i) {
  if (e[i].fg) return;
  --d[e[i].u];
  int x = e[i].u;
  if (!e[i].pre)
    head[x] = e[i].nxt, e[head[x]].pre = 0;
  else
    e[e[i].pre].nxt = e[i].nxt, e[e[i].nxt].pre = e[i].pre;
}
