        public void solve(Scanner sc, PrintWriter pw) throws IOException {
            int n = sc.nextInt();
            int m = sc.nextInt();
            int k = sc.nextInt();
            int[] deg = new int[n];
            List<int[]> edges = new ArrayList<>();
            List<Integer>[] edgesS = new List[n];
            for (int i = 0; i < n; i++) {
                edgesS[i] = new ArrayList<>();
            }
            for (int i = 0; i < m; i++) {
                int a = sc.nextInt() - 1;
                int b = sc.nextInt() - 1;
                edges.add(new int[]{a, b});
                edgesS[a].add(i);
                edgesS[b].add(i);
                deg[a]++;
                deg[b]++;
            }
            boolean[] del = new boolean[n];
            int dlt = 0;
            for (int i = 0; i < n; i++) {
                if (!del[i] && deg[i] < k) {
                    dlt += dfs(i, k, deg, del, edges, edgesS);
                }
            }
            for (int i = 0; i < n; i++) {
                if (!del[i] && deg[i] < k) {
                    dlt += dfs(i, k, deg, del, edges, edgesS);
                }
            }
            int[] res = new int[m];
            res[m - 1] = n - dlt;
            for (int i = m - 1; i > 0; i--) {
                int[] toremove = edges.get(i);
                int t1 = toremove[0], t2 = toremove[1];
                edges.remove(i);
                edgesS[t1].remove(edgesS[t1].size() - 1);
                edgesS[t2].remove(edgesS[t2].size() - 1);
                int tr = 0;
                if (!del[t1] && !del[t2]) {
                    deg[t1]--;
                    deg[t2]--;
                    if (!del[t1] && deg[t1] < k) {
                        tr += dfs(t1, k, deg, del, edges, edgesS);
                    }
                    if (!del[t2] && deg[t2] < k) {
                        tr += dfs(t2, k, deg, del, edges, edgesS);
                    }
                }
                res[i - 1] = res[i] - tr;
            }
            for (int i = 0; i < m; i++) {
                pw.println(res[i]);
            }
        }

        public int dfs(int u, int k, int[] deg, boolean[] del, List<int[]> edges, List<Integer>[] edgeS) {
            int cnt = 0;
            del[u] = true;
            cnt++;
            for (int idx : edgeS[u]) {
                int o = get(edges.get(idx), idx);
                if (del[o]) continue;
                deg[o]--;
                if (deg[o] < k) {
                    cnt += dfs(o, k, deg, del, edges, edgeS);
                }
            }
            return cnt;
        }
    }

