        boolean[] trip = new boolean[n+1];
        for (int i = 1; i <= n; i++) g[i] = new HashSet<>();
        int[] q = new int[n+1];
        int ans = 0;
        while (m-- > 0) {
            int u = readInt(), v = readInt();
            g[u].add(v);
            g[v].add(u);
            if (trip[u] && trip[v]) {
                writer.println(ans);
                continue;
            }
            if (g[u].size() < k || g[v].size() < k) {
                writer.println(ans);
                continue;
            }
            int a = 0, b = 0;
            if (!trip[u] && !trip[v]) {
                if (g[u].size() > k && g[v].size() > k) {
                    writer.println(ans);
                    continue;
                }
                if (g[v].size() == k) {
                    int t = v;
                    v = u;
                    u = t;
                }
                List<Integer> checked = new ArrayList<>();
                boolean ok = true;
                loop:
                for (int x : g[u]) {
                    for (int y : checked)
                        if (!g[y].contains(x)) {
                            ok = false;
                            break loop;
                        }
                    checked.add(x);
                }
                if (ok) {
                    checked.add(u);
                    for (int x : checked) {
                        if (trip[x]) continue;
