void Erase(int u) {
  for (auto v : adj[u]) {
    S.erase(pair<int, int>(adj[v].size(), v));
    adj[v].erase(u);
    if (adj[v].size()) S.insert(pair<int, int>(adj[v].size(), v));
  }
  adj[u].clear();
}
void Remove() {
  while (S.size() && S.begin()->first < k) {
    int u = S.begin()->second;
    Erase(u);
    S.erase(S.begin());
  }
}
