		k = sc.nextInt();

		graph = new Set[n];
		for(int i=0;i<n;i++) {
			graph[i] = new HashSet();
		}

		deg = new int[n];

		List<Edge> edges = new ArrayList<>();
		for(int i=0;i<m;i++) {
			int u = sc.nextInt()-1;
			int v = sc.nextInt()-1;
			edges.add(new Edge(u,v));
			graph[u].add(v);
			graph[v].add(u);
			deg[u]++;
			deg[v]++;
		}

		s = new HashSet<>();
		List<Vertex> ver = new ArrayList<>();
		for(int i=0;i<n;i++) {
			s.add(i);
			ver.add(new Vertex(i,deg[i]));
		}

		ver.sort((v1,v2)->v1.d-v2.d);

		int i=0;
		for(i=0;i<n;i++) {
			if(ver.get(i).d<k) {
				int u = ver.get(i).u;
				if(s.contains(u)) {
					dfs(u);
				}
				else {
					break;
				}
			}
		}

		List<Integer> ans = new ArrayList<>();
		ans.add(s.size());
		for(int j=m-1;j>0;j--) {
			Edge e = edges.get(j);
			graph[e.u].remove(e.v);
			graph[e.v].remove(e.u);
			if(s.contains(e.u) && s.contains(e.v)) {
				dfs(e.u);
				if(s.contains(e.v)) {
					dfs(e.v);
				}
			}
			ans.add(s.size());
		}

		for(int j=ans.size()-1;j>=0;j--) {
			out.println(ans.get(j));
		}
		out.close();
	}

	static void dfs(int u) {
		deg[u]--;
		if(deg[u]>=k) {
			return;
		}
		s.remove(u);
		for(int v:(Set<Integer>) graph[u]) {
			if(s.contains(v)) {
				dfs(v);
			}
		}
	}
}

