void dfs(int x, int last) {
  d[x]--;
  for (int i = head[x]; i; i = nxt[i]) {
    if (ver[i] == last) {
      ver[i] = 0;
      break;
    }
  }
  if (d[x] >= k || cut[x]) return;
  sum--;
  cut[x] = 1;
  for (int i = head[x]; i; i = nxt[i]) {
    int y = ver[i];
    if (y == last)
      ver[i] = 0;
    else if (!cut[y] && y != 0)
      dfs(y, x);
  }
}
