    static class ETrips {
        int[][] G;

        public void solve(int testNumber, ScanReader in, PrintWriter out) {
            int n = in.scanInt();
            int m = in.scanInt();
            int k = in.scanInt();
            TreeSet<pair> bstCustom = new TreeSet<>();
