using namespace std;
const int MAXN = 200011;
struct edge {
  int x, y, pre, nxt;
} E[MAXN << 1];
vector<int> G[MAXN];
int e[MAXN];
int head[MAXN], vis[MAXN], deg[MAXN], ans[MAXN];
int n, m, k, tot = -1, cnt;
inline void AddEdge(int x, int y) {
  E[++tot] = (edge){x, y, -1, head[x]};
  if (head[x] != -1) E[head[x]].pre = tot;
  head[x] = tot;
  E[++tot] = (edge){y, x, -1, head[y]};
  if (head[y] != -1) E[head[y]].pre = tot;
  head[y] = tot;
}
inline void Del(int x, int id) {
  if (head[x] == id) head[x] = E[id].nxt;
  if (E[id].pre != -1) E[E[id].pre].nxt = E[id].nxt;
  if (E[id].nxt != -1) E[E[id].nxt].pre = E[id].pre;
}
inline void Erase(int x) {
  if (vis[x]) return;
  vis[x] = 1;
  --cnt;
  for (int i = head[x]; ~i; i = E[i].nxt) {
    int to = E[i].y;
    --deg[to];
    Del(to, i ^ 1);
    if (deg[to] < k) Erase(to);
  }
}
queue<int> Q;
inline void Calc() {
  for (int i = 1; i <= n; ++i) {
    if (deg[i] < k) {
      vis[i] = 1;
      Q.push(i);
    }
  }
  while (!Q.empty()) {
    int now = Q.front();
    Q.pop();
    for (int i = 0; i < (int)G[now].size(); ++i) {
      --deg[G[now][i]];
      if (deg[G[now][i]] == 0) {
        vis[G[now][i]] = 1;
        Q.push(G[now][i]);
      }
    }
  }
  for (int i = 1; i <= n; ++i) {
    if (!vis[i]) ++cnt;
  }
}
