      continue;
    }
    Del(E[e[i]].x, e[i]);
    Del(E[e[i]].y, e[i] ^ 1);
    --deg[E[e[i]].x];
    --deg[E[e[i]].y];
    if (deg[E[e[i]].x] < k) Erase(E[e[i]].x);
