bool flag[maxN], h[maxN];
pair<int, int> edges[maxM];
set<pair<int, int>> erased;
void dfs1(int u) {
  flag[u] = 1;
  h[u] = 1;
  for (auto &v : adj[u]) {
    if (!flag[v]) {
      dfs1(v);
    }
    cnt[u] += h[v];
  }
  if (cnt[u] < k) {
    h[u] = 0;
  }
}
void dfs2(int u) {
  flag[u] = 1;
  h[u] = 0;
  cur--;
  for (auto &v : adj[u]) {
    if (!flag[v] && h[v] && !erased.count(make_pair(u, v))) {
      cnt[v]--;
      if (cnt[v] < k) {
        dfs2(v);
      }
    }
  }
}
void solve() {
  cin >> n >> m >> k;
  for (int i = 1; i <= (int)(m); ++i) {
    int u, v;
    cin >> u >> v;
    if (u > v) {
      swap(u, v);
    }
    adj[u].emplace_back(v);
    adj[v].emplace_back(u);
    edges[i] = make_pair(u, v);
  }
  for (int i = 1; i <= (int)(n); ++i) {
    if (!flag[i]) {
      dfs1(i);
    }
  }
  for (int i = 1; i <= (int)(n); ++i) {
    cnt[i] = 0;
    for (auto &j : adj[i]) {
      cnt[i] += h[j];
    }
    cur += h[i];
  }
  fill(flag + 1, flag + n + 1, 0);
  for (int i = m; i; i--) {
    int u, v;
    tie(u, v) = edges[i];
    ans[i] = cur;
    if (h[u] && h[v]) {
      cnt[u]--;
      cnt[v]--;
      erased.emplace(u, v);
      erased.emplace(v, u);
      if (!flag[u] && cnt[u] < k) {
        dfs2(u);
      }
      if (!flag[v] && cnt[v] < k) {
        dfs2(v);
      }
    }
  }
  for (int i = 1; i <= (int)(m); ++i) {
    cout << ans[i] << "\n";
  }
}
