const int ms = 200200;
int n, m, k;
int ans = 0;
int size[ms], par[ms];
std::pair<int, int> edges[ms];
std::vector<int> use[ms], dels[ms];
int deg[ms];
bool del[ms];
int getPar(int x) { return x == par[x] ? x : par[x] = getPar(par[x]); }
void makeUnion(int a, int b) {
  a = getPar(a);
  b = getPar(b);
  if (a == b) return;
  if (size[a] < size[b]) {
    std::swap(a, b);
  }
  size[a] += size[b];
  ans = std::max(size[a], ans);
  par[b] = a;
}
int main() {
  std::cin >> n >> m >> k;
  for (int i = 1; i <= n; i++) {
    par[i] = i;
    size[i] = 1;
  }
  for (int i = 0; i < m; i++) {
    int u, v;
    scanf("%d %d", &u, &v);
    use[u].push_back(i);
    use[v].push_back(i);
    deg[u]++;
    deg[v]++;
    edges[i] = std::pair<int, int>(u, v);
  }
  std::queue<int> q;
  for (int i = 1; i <= n; i++) {
    if (deg[i] < k) {
      q.push(i);
    }
  }
  del[m] = true;
  for (int i = m; i >= 0; i--) {
    if (!del[i]) {
      int u = edges[i].first, v = edges[i].second;
      if (deg[u] == k) {
        q.push(u);
      }
      if (deg[v] == k) {
        q.push(v);
      }
      deg[u]--;
      deg[v]--;
      del[i] = true;
      dels[i].push_back(i);
    }
    while (!q.empty()) {
      int on = q.front();
      q.pop();
      for (auto e : use[on]) {
        if (!del[e]) {
          int u = edges[e].first, v = edges[e].second;
          if (deg[u] == k) {
            q.push(u);
          }
          if (deg[v] == k) {
            q.push(v);
          }
          deg[u]--;
          deg[v]--;
          del[e] = true;
          dels[i].push_back(e);
        }
      }
    }
  }
  for (int i = 0; i < m; i++) {
    for (auto e : dels[i]) {
      int u = edges[e].first, v = edges[e].second;
      makeUnion(u, v);
