	mylist N[];
	void correctSet(){
		while(!s.isEmpty()){
 			if(s.first().x>=k) break;
 			int u = s.pollFirst().y;
 			for(int v : N[u]) if(s.contains(new pair(d[v],v))){
 				s.remove(new pair(d[v],v));
 				d[v]--;
 				s.add(new pair(d[v],v));
 			}
 		}
	}
 	public void Solve() throws IOException{
 		n = ip.i();
