 		for(int i=0 ; i<m ; i++){
 			int u = ip.i(); int v = ip.i(); 
 			E[i] = new pair(u,v);
 			N[u].add(v); N[v].add(u);
 			d[u]++; d[v]++;
 		}
 		s = new myset();
 		for(int i=1 ; i<=n ; i++) s.add(new pair(d[i],i));
 		correctSet();
 		mylist res = new mylist();
 		for(int i=(m-1) ; i>=0 ; i--){
 			res.add(s.size());
 			int u = E[i].x; int v = E[i].y;
 			boolean uins = s.contains(new pair(d[u],u));
 			boolean vins = s.contains(new pair(d[v],v));
