 			s.remove(new pair(d[u],u));
 			s.remove(new pair(d[v],v));
 			d[u]--; d[v]--;
 			N[u].remove(N[u].size()-1);
 			N[v].remove(N[v].size()-1);
 			s.add(new pair(d[u],u));
 			s.add(new pair(d[v],v));
 			correctSet();
 		}
 		Collections.reverse(res);
 		for(int elem : res) pln(elem);
