void update(int a, vector<set<int> >& g, set<pair<int, int> >& s, int k) {
  for (int v : g[a]) {
    s.erase({g[v].size(), v});
    g[v].erase(a);
    if (g[v].size() >= k) {
      s.insert({g[v].size(), v});
    }
  }
