};
l MAXC = 1000;
struct Graph {
  l v, e;
  vector<vector<Edge>> adj;
  vvl counter;
  l k;
  l good;
  Graph(l n, l k) : v(n), e(0), k(k), good(0) {
    adj.resize(v);
    counter.resize(v, vl(MAXC));
  }
  l add_node() {
    adj.resize(++v);
    return v - 1;
  }
  void add_simple(l a, l b) {
    Edge ab;
    ab.to = b;
    adj[a].emplace_back(ab);
    e++;
  }
  void add_undirected(l a, l b) {
    Edge ab;
    ab.id = e;
    ab.from = a;
    ab.to = b;
    adj[a].emplace_back(ab);
    Edge ba;
    ba.id = e;
    ba.from = b;
    ba.to = a;
    adj[b].emplace_back(ba);
    e++;
    for (l i = l(0); i < l(MAXC - 1); i++)
      if (counter[a][i] == k) inc(b, i + 1);
    for (l i = l(0); i < l(MAXC - 1); i++)
      if (counter[b][i] == k) inc(a, i + 1);
    inc(a, 0);
    inc(b, 0);
  }
  void inc(l a, int j) {
    if (counter[a][j] == k) return;
    counter[a][j]++;
    if (counter[a][j] != k) return;
    if (j + 1 == MAXC) {
      good++;
    } else {
      for (auto edge : adj[a]) inc(edge.to, j + 1);
    }
  }
  void add_directed(l a, l b) {
    Edge ab;
    ab.id = e;
    ab.from = a;
    ab.to = b;
    adj[a].emplace_back(ab);
    e++;
  }
};
void solve(istream& in, ostream& out) {
  l n, m, k;
  in >> n >> m >> k;
  MAXC = e5 / n;
  (MAXC);
  Graph g(n, k);
  for (l i = l(0); i < l(m); i++) {
    l a, b;
    in >> a >> b;
    a--;
    b--;
    g.add_undirected(a, b);
    out << g.good << lf;
  }
}
