			if(ver.get(i).d<k) {
				int u = ver.get(i).u;
				if(s.contains(u)) {
					dfs(u);
				}
				else {
					break;
				}
			}
		}

		ArrayList<Integer> ans = new ArrayList<>();
		ans.add(s.size());
		for(int j=m-1;j>0;j--) {
			Edge e = edges.get(j);
			graph[e.u].remove(e.v);
