using namespace std;
int u[400100], v[400100], fir[200100], nxt[400100], cnt = 0, n, m, k;
int dis[200100], ans = 0;
void addedge(int ui, int vi) {
  ++cnt;
  u[cnt] = ui;
  v[cnt] = vi;
  nxt[cnt] = fir[ui];
  fir[ui] = cnt;
}
void dfs(int u) {
  for (int i = fir[u]; i; i = nxt[i]) {
    if (!dis[v[i]]) {
      dis[v[i]] = dis[u] + 1;
      dfs(v[i]);
    } else {
      ans = max(ans, abs(dis[u] - dis[v[i]]) + 1);
    }
  }
}
void findmax(void) {
  memset(dis, 0, sizeof(dis));
  ans = 1;
  for (int i = 1; i <= n; i++)
    if (!dis[i]) dfs(i);
}
