        }

        io.flush();
    }

    public static class Task implements Runnable {
        final FastIO io;

        public Task(FastIO io) {
            this.io = io;
        }

        @Override
        public void run() {
            solve();
        }

        public void solve() {
            int n = io.readInt();
            Node[] nodes = new Node[n + 1];
            for (int i = 0; i <= n; i++) {
                nodes[i] = new Node();
                nodes[i].id = i;
            }

            for (int i = 1; i < n; i++) {
                Node a = nodes[io.readInt()];
                Node b = nodes[io.readInt()];

                a.set.add(b);
                b.set.add(a);
            }

            int[] seq = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                int v = io.readInt();
                seq[i] = v;
                if (v <= 0 || v > n) {
                    io.cache.append("No");
                    return;
                }
                if (nodes[v].seq != -1) {
                    io.cache.append("No");
                    return;
                }
                nodes[v].seq = i;
            }

            if(seq[1] != 1)
            {
                io.cache.append("No");
                return;
            }

            Node root = nodes[seq[1]];
            Deque<Node> deque = new ArrayDeque<>(n);
            deque.add(root);

            int offset = 2;
            while (!deque.isEmpty()) {
                Node head = deque.removeFirst();
                int allowRange = offset + head.set.size();
                for (; offset < allowRange; offset++) {
                    Node next = nodes[seq[offset]];
                    if (!head.set.contains(next)) {
                        io.cache.append("No");
                        return;
                    }
                    next.set.remove(head);
                    deque.add(next);
                }
            }

            io.cache.append("Yes");
            return;
        }

    }

