      Q.push(i);
      Inqueue[i] = true;
    }
  while (!Q.empty()) {
    int x = Q.front();
    Q.pop();
    vis[x] = false;
    --Ans;
    for (int i = link[x]; i; i = nxt[i])
      if (used[i]) {
        int v = toit[i];
        if (!vis[v]) continue;
        --du[v];
        if (du[v] < k && !Inqueue[v]) {
