    static class TaskE {
        Set[] g;
        int[] deg;
        Set<Integer> s;
        int k;
        int n;
        Set<Integer> vis;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            n = in.nextInt();
            int m = in.nextInt();
            k = in.nextInt();

            g = new Set[n];

            for (int i = 0; i < n; i++) {
                g[i] = new HashSet();
            }

            deg = new int[n];

            List<edge> edges = new ArrayList<>();
            for (int i = 0; i < m; i++) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;
                edges.add(new edge(u, v));
                g[u].add(v);
                g[v].add(u);
                deg[u]++;
                deg[v]++;
            }


            s = new HashSet<>();

            List<vertex> vertices = new ArrayList<>();

            for (int i = 0; i < n; i++) {
                s.add(i);
                vertices.add(new vertex(i, deg[i]));
            }

            vertices.sort((v1, v2) -> v1.d - v2.d);

            int i = 0;
            for (i = 0; i < n; i++) {
                if (vertices.get(i).d < k) {
                    int u = vertices.get(i).u;
                    if (s.contains(u))
                        dfs(u, -1, -1);
                } else {
                    break;
                }
            }

            //out.println(s.size());
            List<Integer> ans = new ArrayList<>();
            ans.add(s.size());
            for (int j = m - 1; j > 0; j--) {
                edge ce = edges.get(j);
                vis = new HashSet<>();
                if (s.contains(ce.u) && s.contains(ce.v)) {
//                ArrayDeque<Integer> q = new ArrayDeque<>();
//
