//                        }
//                    }
//                }

                    dfs(ce.u, ce.v, ce.u);
                    dfs(ce.v, ce.u, ce.v);
                }

                g[ce.u].remove(ce.v);
                g[ce.v].remove(ce.u);

                ans.add(s.size());
                //out.println(s.size());
            }

            for (int j = ans.size() - 1; j >= 0; j--) {
