        void dfs(int u, int ov, int ou) {
            deg[u]--;

            if (deg[u] >= k) {
                return;
            }

            s.remove(u);

            for (int v : (Set<Integer>) g[u]) {
                if (s.contains(v) && (ou != u || ov != v)) {
                    dfs(v, ov, ou);
                }
            }


