const int N = 200001;

vector<int> g[N];
int v[N], k, ans[N], c[N];

bool dfs(int node)
{
	v[node] = 1;
	int cnt = 0;
	for(int &it : g[node])
	{
		if(!v[it])
			cnt += dfs(it);
		else if(v[it] > 0)
			cnt++;
	}
	c[node] = cnt;
	if(cnt >= k)
		v[node] = 2;
	else
		v[node] = -1;
	return (v[node] == 2);
}

int rem(int node)
{
	if(c[node] >= k or v[node] == -2)
		return 0;
	v[node] = -2;
	int ret = 1;
	for(int &it : g[node])
	{
		if(c[it] >= k)
		{
			c[it]--;
			ret += rem(it);
		}
	}
	return ret;
}

