/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE {
        int n;
        int m;
        int k;
        Set<Integer> going = new HashSet<>();

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            n = in.nextInt();
            m = in.nextInt();
            k = in.nextInt();
            Vertex[] vs = new Vertex[n];
            for (int i = 0; i < n; ++i) {
                vs[i] = new Vertex(i);
            }
            for (int i = 0; i < m; ++i) {
                int x = in.nextInt() - 1;
                int y = in.nextInt() - 1;
                vs[x].adj.add(vs[y]);
                vs[y].adj.add(vs[x]);
                vs[x].canGo();
                vs[y].canGo();
                out.println(going.size());
            }
        }

        enum State {
            CAN_GO,
            DECIDING,
            UNDECIDED,
            ;
        }

        class Vertex {
            int id;
            TaskE.State state = TaskE.State.UNDECIDED;
            List<Vertex> adj = new ArrayList<>();

            Vertex(int id) {
                this.id = id;
            }

            boolean canGo() {
                if (this.state == TaskE.State.CAN_GO) return true;
                if (this.adj.size() < k) return false;
                this.state = TaskE.State.DECIDING;
                int count = 0;
                for (int i = 0; i < this.adj.size(); ++i) {
                    int rem = this.adj.size() - i;
                    int remCount = k - count;
                    if (rem < remCount) {
                        this.state = TaskE.State.UNDECIDED;
                        return false;
                    }
                    Vertex v = this.adj.get(i);
                    if (v.state == TaskE.State.DECIDING) {
                        ++count;
                        continue;
                    }
                    boolean cur = v.canGo();
                    if (cur) {
                        ++count;
                    }
                }
                if (count >= k) {
                    this.state = TaskE.State.CAN_GO;
                    going.add(this.id);
                } else {
                    this.state = TaskE.State.UNDECIDED;
                }
                return count >= k;
            }

        }

    }

    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

