public class E {

    static ArrayList<Integer>[] adj;
    static int[] vis, going;
    static int NO = 3, YES = 2, VIS = 1;
    static int k;
    public static void main(String[] args) throws IOException{
        Scanner sc = new Scanner();
        PrintWriter pw = new PrintWriter(System.out);

        int n = sc.nextInt();
        adj = new ArrayList[n];
        for (int i = 0; i < adj.length; i++) {
            adj[i] = new ArrayList<>();
        }
        vis = new int[n];
        going = new int[n];

        int m = sc.nextInt();
        k = sc.nextInt();

        HashSet<Long> e = new HashSet<>();
        int[][] edges = new int[m][2];
        for (int i = 0; i < m; i++) {
            edges[i][0] = sc.nextInt()-1;
            edges[i][1] = sc.nextInt()-1;

            adj[edges[i][0]].add(edges[i][1]);
            adj[edges[i][1]].add(edges[i][0]);

            e.add(hash(edges[i][0], edges[i][1]));
        }

        for (int i = 0; i < n; i++) {
            if(vis[i] == 0)
                go(i);
        }

        TreeSet<Integer> set = new TreeSet<>(new Comparator<Integer>() {
            @Override
            public int compare(Integer i, Integer j) { ;
                if(going[i] != going[j])
                    return going[i] - going[j];
                return i - j;
            }
        });

        for (int i = 0; i < n; i++) {
            if(vis[i] == YES)
                set.add(i);
        }

        int[] ans = new int[m];
        for (int q = m-1; q >= 0; q--) {
            ans[q] = set.size();
            int u = edges[q][0];
            int v = edges[q][1];

            if(vis[u] == YES) {
                set.remove(u);
                if(vis[v] == YES && e.contains(hash(u, v)))
                    going[u]--;
                set.add(u);
            }

            if(vis[v] == YES) {
                set.remove(v);
                if(vis[u] == YES && e.contains(hash(u, v)))
                    going[v]--;
                set.add(v);
            }

            e.remove(hash(u, v));


            while(!set.isEmpty() && going[set.first()] < k){
                int a = set.pollFirst();
                vis[a] = NO;
                for (int b : adj[a]) {
                    if(vis[b] == YES && e.contains(hash(a, b))){
                        set.remove(b);
                        going[b]--;
                        set.add(b);
                        e.remove(hash(a, b));
                    }
                }
            }
        }

        ans[0] = set.size();

        for (int i = 0; i < m; i++) {
            pw.println(ans[i]);
        }


        pw.flush();
        pw.close();
    }

    static void go(int u){
        int g = 0;
        vis[u] = YES;
        for (int v: adj[u]) {
            if(vis[v] == YES)
                g++;
            else if(vis[v] == 0)
            {
                vis[v] = VIS;
                go(v);
                if(vis[v] == YES)
                    g++;
            }
        }

        going[u] = g;

        if(g < k)
            vis[u] = NO;
    }

    static long hash(int a, int b){
        return Math.min(a, b) * 1000000l + Math.max(a, b);
    }
