vector<vector<int> > graph;
vector<int> edges;
vector<pair<int, int> > days;
vector<bool> vis;
vector<bool> correct;
int previous = 0;
bool DFS(int v, int k) {
  if ((int)(graph[v].size()) < k) {
    correct[v] = false;
    return false;
  }
  int works = 0;
  for (auto& u : graph[v]) {
    if (!vis[u]) {
      vis[u] = true;
      correct[u] = true;
      if (DFS(u, k)) {
        ++works;
      }
    } else {
      if (correct[u]) {
        ++works;
      }
    }
  }
  if (works < k) {
    correct[v] = false;
  }
  return correct[v];
}
void ERASE(int v, int x, int k) {
  if ((int)(graph[v].size()) > k) {
    return;
  }
  correct[v] = false;
  --previous;
  for (auto& u : graph[v]) {
    if (correct[u] && u != x) {
      --edges[u];
      ERASE(u, -1, k);
    }
  }
}
