  }
  for (int i = (0); i < (n); ++i) {
    if (!vis[i]) {
      vis[i] = true;
      correct[i] = true;
      DFS(i, k);
    }
  }
  for (int i = (0); i < (n); ++i) {
    if (correct[i]) {
      ++previous;
    }
  }
  for (int i = (0); i < (n); ++i) {
    if (correct[i]) {
      for (auto& u : graph[i]) {
        if (!correct[u]) {
          --edges[i];
        }
      }
    }
  }
  stack<int> result;
  for (int i = (int)(days.size()) - 1; i >= 0; --i) {
