		ArrayList<Edge> edges = new ArrayList<Edge>();
		for(int i=0;i<m;i++) {
			int u = sc.nextInt()-1;
			int v = sc.nextInt()-1;
			edges.add(new Edge(u,v));
			graph[u].add(v);
			graph[v].add(u);
			deg[u]++;
			deg[v]++;
		}

		s = new HashSet<Integer>();
		ArrayList<Vertex> ver = new ArrayList<>();
		for(int i=0;i<n;i++) {
			s.add(i);
			ver.add(new Vertex(i,deg[i]));
