		int i=0;
		for(i=0;i<n;i++) {
			if(ver.get(i).d<k) {
				int u = ver.get(i).u;
				if(s.contains(u)) {
					dfs(u);
				}
				else {
					break;
				}
			}
		}

		ArrayList<Integer> ans = new ArrayList<>();
		ans.add(s.size());
		for(int j=m-1;j>0;j--) {
			Edge e = edges.get(j);
			graph[e.u].remove(e.v);
			graph[e.v].remove(e.u);
			if(s.contains(e.u) && s.contains(e.v)) {
				dfs(e.u);
				if(s.contains(e.v)) {
					dfs(e.v);
				}
			}
			ans.add(s.size());
		}

		for(int j=ans.size()-1;j>=0;j--) {
			System.out.println(ans.get(j));
		}
	}

	static void dfs(int u) {
		deg[u]--;
		if(deg[u]>=k) {
			return;
		}
		s.remove(u);
		for(int v:(Set<Integer>) graph[u]) {
			if(s.contains(v)) {
				dfs(v);
			}
		}
	}
