    s.erase(it);
    for (auto it1 = e[x].begin(); it1 != e[x].end(); it1++) {
      int y = *it1;
      e[y].erase(x);
      if (d[y] >= k) {
        s.erase({d[y], y});
        d[y]--;
        s.insert({d[y], y});
      }
    }
    e[x].clear();
  }
}
