        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(reader.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        k = Integer.parseInt(st.nextToken());
        s = new HashSet<>(2*m);
        g = new Set[n];
        degree = new int[n];
        for (int i = 0; i < n; i++) {
            g[i] = new HashSet<>();
        }
        int[][] f = new int[m][2];
        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(reader.readLine());
            int a = Integer.parseInt(st.nextToken())-1;
            int b = Integer.parseInt(st.nextToken())-1;
            g[a].add(new Pair(b,i));
            g[b].add(new Pair(a,i));
            degree[a]++;degree[b]++;
            s.add(a);s.add(b);
            f[i][0] = a;
            f[i][1] = b;
        }
        for (int i = 0; i < n; i++) {
            if(g[i].isEmpty()){
                s.remove(i);
            } else if(g[i].size() < k) {
                q.add(i);
                s.remove(i);
            }
        }
        while (!q.isEmpty()){
            int v = q.poll();
            for (Pair u : g[v]) {
                if(s.contains(u.a)) {
                    degree[u.a]--;
                    if (degree[u.a] < k) {
                        q.add(u.a);
                    }
                }
            }
            s.remove(v);
        }
        int[] ans = new int[m];
        for (int i = m-1; i >=0; i--) {
            ans[i] = s.size();
            int a = f[i][0];
            int b = f[i][1];
            if(s.contains(a) && s.contains(b)) {
                degree[a]--;degree[b]--;
                if (degree[a] < k) q.add(a);
                if (degree[b] < k) q.add(b);
                while (!q.isEmpty()){
                    int v = q.poll();
                    for (Pair u : g[v]) {
                        if(s.contains(u.a) && u.b < i) {
                            degree[u.a]--;
                            if (degree[u.a] < k) {
                                q.add(u.a);
                            }
                        }
                    }
                    s.remove(v);
                }
            }
        }
        for (int i = 0; i < m; i++) {
            System.out.println(ans[i]);
        }

    }
