const int maxn = 2e5 + 5;
pair<int, int> ed[maxn];
vector<int> g[maxn];
int n, m, k, fa[maxn], d[maxn];
int cl[maxn], fcl[maxn], ans[maxn];
int vs[maxn], sz;
bool v[maxn], w[maxn], us[maxn];
void dfs(int x, int p) {
  fa[x] = p;
  d[x] = p == -1 ? 0 : d[p] + 1;
  v[x] = true;
  for (int u : g[x]) {
    if (d[u] < d[x]) w[d[x] - d[u]] = true;
  }
  int i = 0;
  while (w[i + 1]) ++i;
  cl[x] = i + 1;
  if (~p) cl[x] = min(cl[x], cl[p] + 1);
  for (int u : g[x]) {
    if (d[u] < d[x]) w[d[x] - d[u]] = false;
  }
  fcl[x] = cl[x];
  if (~p && cl[p] == cl[x] - 1) {
    fcl[p] = max(fcl[p], fcl[x]);
  }
  for (int u : g[x]) {
    if (v[u]) continue;
    dfs(u, x);
  }
  vs[sz++] = x;
}
int check(int t) {
  sz = 0;
  for (int i = 0; i < n; ++i) g[i].clear();
  for (int i = 1; i <= t; ++i) {
    int x = ed[i].first, y = ed[i].second;
    g[x].push_back(y);
    g[y].push_back(x);
  }
  for (int i = 0; i < n; ++i) v[i] = false;
  for (int i = 0; i < n; ++i) {
    if (v[i]) continue;
    dfs(i, -1);
  }
  for (int i = 0; i < n; ++i) us[i] = false;
  int ans = 0;
  for (int i = 0; i < n; ++i) {
    int x = vs[i];
    if (fa[x] == -1) continue;
    if (cl[x] <= k) continue;
    if (us[x]) continue;
    if (cl[x] == fcl[x]) {
      for (int j = 0; j < fcl[vs[i]]; ++j) {
        if (!us[x]) ++ans;
        us[x] = true;
        x = fa[x];
      }
    }
  }
  return ans;
}
int main() {
  scanf("%d %d %d", &n, &m, &k);
  for (int i = 1; i <= m; ++i) {
    int x, y;
    scanf("%d %d", &x, &y);
    --x, --y;
    ed[i] = make_pair(x, y);
  }
  int last = 0;
  for (int i = 0; i <= n; ++i) {
    int d = 20, t = last;
    while (d--)
      if (t + (1 << d) <= m) {
        if (check(t + (1 << d)) == i) t += (1 << d);
      }
    for (int j = last + 1; j <= t; ++j) ans[j] = i;
    last = t;
  }
  for (int i = 1; i <= m; ++i) printf("%d\n", ans[i]);
  return 0;
}
