public class Trips {
    static Pair[] pairs;
    static ArrayList<Integer> graph[];
    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        StringBuilder sb = new StringBuilder();
        ArrayDeque<Integer> st = new ArrayDeque<>();
        ArrayDeque<Pair> edges = new ArrayDeque<>();
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        //Adjacency List
        graph = new ArrayList[n+1];
        pairs = new Pair[n+1];
        for (int i = 0; i< n+1; i++) {
            graph[i] = new ArrayList();
        }
        //int sizes[] = new int[n+1];
        for (int i = 0; i < m;i++) {
            int p1 = sc.nextInt();
            int p2 = sc.nextInt();
            graph[p1].add(p2);
            graph[p2].add(p1);
            edges.push(new Pair(p1, p2));
        }
        for(int i = 0; i < n+1;i++) {
            pairs[i] = new Pair(i, graph[i].size());
        }
        int prevTrip = checkTrip(k, n);
        st.push(prevTrip);
        //for(int i = 1; i < n+1;i++) {
         //   System.out.println("i: " + i + ": " + pairs[i].b);
        //}
        //System.out.println(edges.size());
        while(!edges.isEmpty()) {
            Pair edge = edges.pop();
            int node1 = edge.a;
            int node2 = edge.b;
            //System.out.println("removed edge: " + node1 + " " + node2);
            if (pairs[node1].b < 1 || pairs[node2].b < 1) {
                st.push(prevTrip);
            }
            else {
                pairs[node1].b--;
                pairs[node2].b--;
                if (pairs[node1].b < k && pairs[node2].b >= k) {
                    pairs[node2].b++;
                    prevTrip = checkTrip(k, n);
                }
                if (pairs[node2].b < k || pairs[node1].b >= k) {
                    pairs[node1].b++;
                    prevTrip = checkTrip(k, n);
                }
                if (pairs[node1].b < k && pairs[node2].b < k) {
                    prevTrip = checkTrip(k, n);
                }
                //System.out.println("NEW UPDATES");
                //for (int i = 1; i < n + 1; i++) {
                 //   System.out.println("i: " + i + ": " + pairs[i].b);
                //}
                st.push(prevTrip);
            }
        }
        //System.out.println(st.size());
        //last edge removed will always be 0
        st.pop();
        while(!st.isEmpty()) {
            sb.append(st.pop());
            sb.append('\n');
        }
        System.out.print(sb.toString());

    }

    public static int checkTrip(int k, int n) {
        boolean removed = false;
        int sum = 0;
        for (int i = 1; i < n+1 ;i++) {
            if (pairs[i].b > 0 && pairs[i].b < k) {
                removed = true;
                for (int e: graph[i]) {
                    --pairs[e].b;
                }
                pairs[i].b = 0;
            }
            else if (pairs[i].b >= k) {
                sum++;
            }
        }
        if (removed) {
            return checkTrip(k, n);
        }
        return sum;
    }
    public static class Pair{
        int a,b;
        public Pair(int a, int b) {this.a=a;this.b=b;}
    }

