void intialize(int n) {
  for (int i = 1; i <= n; i++) {
    ar[i] = i;
    si[i] = 1;
  }
}
int root(int x) {
  if (ar[x] == x) return x;
  return ar[x] = root(ar[x]);
}
void uni(int x, int y) {
  int rx = root(x);
  int ry = root(y);
  de[x]++;
  de[y]++;
  if (de[x] == k) ss[rx]++;
  if (de[y] == k) ss[ry]++;
  if (si[x] > si[y]) {
    ar[ry] = rx;
    si[rx] += si[ry];
    ss[rx] += ss[ry];
  } else {
    ar[rx] = ry;
    si[ry] += si[rx];
    ss[ry] += ss[rx];
  }
}
int res(int x, int y) {
  int rx = root(x);
  int ry = root(y);
  if (rx != ry) {
    uni(x, y);
    int rr = root(x);
    if (si[rr] == ss[rr]) ans = max(ans, si[rr]);
