ll f(vector<set<ll>> &E, vb &D, queue<ll> &q, ll &K) {
    ll res = 0;
    while(!q.empty()) {
        ll curr = q.front();
        q.pop();

        D[curr] = false;
        res++;

        for(ll nex : E[curr]) {
            E[nex].erase(curr);

            if(len(E[nex]) >= K)
                continue;

            q.push(nex);
            D[nex] = false;
        }
        E[curr].clear();
    }

    return res;
}

