int mark[500009], deg[500009];
void solve() {
  scanf("%d", &n);
  scanf("%d", &m);
  scanf("%d", &k);
  int e1[100009], e2[100009];
  vector<pair<int, int> > vec[n + 9];
  for (int i = 1; i <= m; i++) {
    int x, y;
    scanf("%d", &x);
    scanf("%d", &y);
    deg[x]++;
    deg[y]++;
    vec[x].push_back({y, i});
    vec[y].push_back({x, i});
    e1[i] = x;
    e2[i] = y;
  }
  set<pair<int, int> > s;
  set<pair<int, int> >::iterator it;
  for (int i = 1; i <= n; i++) {
    s.insert({deg[i], i});
    mark[i] = 1;
  }
  while (s.size() > 0) {
    it = s.begin();
    if (it->first >= k)
      break;
    else {
      int ele = (it->second);
      for (int i = 0; i < vec[ele].size(); i++) {
        int nxt = vec[ele][i].first;
        if (mark[nxt]) {
          s.erase({deg[nxt], nxt});
          deg[nxt]--;
          s.insert({deg[nxt], nxt});
        }
      }
      s.erase({deg[ele], ele});
      mark[ele] = 0;
    }
  }
  int query[m + 9];
  for (int i = m; i >= 1; i--) {
    query[i] = s.size();
    int x = e1[i];
    int y = e2[i];
    if (mark[x] == 1 && mark[y] == 1) {
      s.erase({deg[y], y});
      s.erase({deg[x], x});
      deg[x]--;
      deg[y]--;
      s.insert({deg[x], x});
      s.insert({deg[y], y});
      while (s.size() > 0) {
        it = s.begin();
        if (it->first >= k)
          break;
        else {
          int ele = (it->second);
          for (int ii = 0; ii < vec[ele].size(); ii++) {
            int nxt = vec[ele][ii].first;
            if (mark[nxt] && vec[ele][ii].second < i) {
              s.erase({deg[nxt], nxt});
              deg[nxt]--;
              s.insert({deg[nxt], nxt});
            }
          }
          s.erase({deg[ele], ele});
          mark[ele] = 0;
        }
      }
    }
  }
  for (int i = 1; i <= m; i++) printf("%d\n", query[i]);
}
