void ukloni(int x, int tijme) {
  removed[x] = true;
  cnt--;
  for (auto e : E[x]) {
    if (removed[e.first] || e.second >= tijme) continue;
    deg[e.first]--;
    if (deg[e.first] < k) ukloni(e.first, tijme);
  }
}
