public class e{ 
	static List<Edge> edges[];
	static int[] esize;
	static boolean[] stay;
	static boolean[] used;
	static int k;
	static int[] u,v;
	static int bfs(int id){
		int res =0;
		esize[u[id]]--;esize[v[id]]--;
		used[id]=true;
		Deque<Integer> que = new ArrayDeque<>();
		if(esize[u[id]]<k){
			que.add(u[id]);
			stay[u[id]]=true;
			++res;
		}
		if(esize[v[id]]<k){
			que.add(v[id]);
			stay[v[id]]=true;
			++res;
		}
		while(!que.isEmpty()){
			int p = que.poll();
			esize[p]=0;
			for(Edge e: edges[p])if(!used[e.id] && !stay[e.to]){
				used[e.id]=true;
				esize[e.to]--;
				if(esize[e.to]<k){
					que.add(e.to);stay[e.to]=true;
					++res;
				}
			}
		}
		return res;
	}

	static class Edge{
		int to, id;
		Edge(int to, int id){this.to=to;this.id=id;}
	}

	static void solve(){
		int n =ni(), m=ni();
		k=ni();
		u = new int[m];
		v = new int[m];
		edges = new List[n];
		used = new boolean[m];
		for(int i=0;i<n;++i)edges[i]=new ArrayList<>();
		for(int i=0;i<m;++i){
			u[i]=ni()-1;
			v[i]=ni()-1;
			edges[u[i]].add(new Edge(v[i], i));
			edges[v[i]].add(new Edge(u[i], i));
		}

		int remain = n;

		esize= new int[n];
		for(int i=0;i<n;++i)esize[i]=edges[i].size();
		stay = new boolean[n];


		Deque<Integer> que = new ArrayDeque<>();
		for(int i=0;i<n;++i)if(esize[i]<k){
			que.add(i);
			stay[i]=true;
			--remain;
		}

