using namespace std;
struct Hasher {
  size_t operator()(const pair<int, int>& pr) const {
    return (size_t)pr.first * (size_t)200000 + (size_t)pr.second;
  }
};
int n, m, k, active_people;
vector<pair<int, int>> friendships;
unordered_set<pair<int, int>, Hasher> are_friends;
unordered_map<int, vector<int>> edges;
vector<int> no_active_friends;
void deactivate_man(int x) {
  static queue<int> transitive;
  transitive.push(x);
  while (!transitive.empty()) {
    const int victim = transitive.front();
    transitive.pop();
    active_people -= 1;
    for (const int fr : edges[victim])
      if (are_friends.find({victim, fr}) != are_friends.end()) {
        no_active_friends.at(fr) -= 1;
        if (no_active_friends.at(fr) == k - 1) transitive.push(fr);
      }
  }
}
int main() {
  ios::sync_with_stdio(0);
  cin >> n >> m >> k;
  active_people = n;
  friendships.reserve(m);
  no_active_friends.resize(n, 0);
  for (int i = 0; i < m; ++i) {
    int a, b;
    cin >> a >> b;
    a -= 1;
    b -= 1;
    friendships.emplace_back(a, b);
    edges[a].push_back(b);
    edges[b].push_back(a);
    no_active_friends.at(a)++;
    no_active_friends.at(b)++;
    are_friends.emplace(a, b);
    are_friends.emplace(b, a);
  }
  for (int i = 0; i < n; ++i)
    if (no_active_friends.at(i) < k) no_active_friends.at(i) = k - 1;
  for (int i = 0; i < n; ++i)
    if (no_active_friends.at(i) == k - 1) deactivate_man(i);
  vector<int> answers;
  answers.reserve(m);
  for (int i = m - 1; i >= 0; --i) {
    int a, b;
    tie(a, b) = friendships.at(i);
    answers.push_back(active_people);
    if (no_active_friends.at(a) == k && no_active_friends.at(b) == k)
      no_active_friends.at(a) -= 1, deactivate_man(a);
    else if (no_active_friends.at(a) > k && no_active_friends.at(b) == k)
      no_active_friends.at(b) -= 1, deactivate_man(b);
    else if (no_active_friends.at(a) == k && no_active_friends.at(b) > k)
      no_active_friends.at(a) -= 1, deactivate_man(a);
    else if (no_active_friends.at(a) > k && no_active_friends.at(b) > k)
      no_active_friends.at(a) -= 1, no_active_friends.at(b) -= 1;
    are_friends.erase({a, b});
    are_friends.erase({b, a});
  }
  for (int i = m - 1; i >= 0; --i) cout << answers.at(i) << '\n';
  return 0;
}
