#include <bits/stdc++.h>
using namespace std;
const int N = 400100;
int cat(1), head[N] = {0};
struct Edge {
  int fr, p, nt;
  Edge() : fr(0), p(0), nt(0) {}
  Edge(int _fr, int _p, int _nt) { fr = _fr, p = _p, nt = _nt; }
} lk[N << 1];
inline void Ins(int In_po1, int In_po2) {
  lk[++cat] = Edge(In_po1, In_po2, head[In_po1]);
  head[In_po1] = cat;
}
int ans[N];
int ind[N];
int vis[N], visE[N];
queue<int> q;
int nn, be[N], num[N];
void dfs(int o) {
  num[be[o] = nn]++;
  for (int i = head[o]; i; i = lk[i].nt) {
    int po = lk[i].p;
    if (vis[po] || be[po]) continue;
    dfs(po);
  }
}
int s[N], siz, pos[N];
inline void init() { siz = 0; }
inline bool empty() { return siz == 0; }
inline bool cmp(int ca, int cb) { return num[s[ca]] > num[s[cb]]; }
inline void Swap(int ca, int cb) {
  swap(pos[s[ca]], pos[s[cb]]), swap(s[ca], s[cb]);
}
inline void up(int o) {
  for (int p; (p = o >> 1) > 0 && cmp(o, p); o = p) Swap(o, p);
}
inline void down(int o) {
  for (int p; (p = o << 1) <= siz; o = p) {
    if (p < siz && cmp(p + 1, p)) p++;
    if (cmp(p, o))
      Swap(o, p);
    else
      break;
  }
}
inline int pop() {
  Swap(1, siz--), down(1);
  return s[siz + 1];
}
inline void push(int o) { s[++siz] = o, pos[o] = siz, up(siz); }
inline void upd(int o) {
  q.push(o), vis[o] = 1;
  num[be[o]]--, down(pos[be[o]]);
}
int main() {
  int n, m, k, po1, po2;
  scanf("%d%d%d", &n, &m, &k);
  for (int i = 1; i <= m; ++i) {
    scanf("%d%d", &po1, &po2);
    Ins(po1, po2), Ins(po2, po1);
    ind[po1]++, ind[po2]++;
  }
  for (int i = 1; i <= n; ++i)
    if (ind[i] < k) q.push(i), vis[i] = 1;
  int o;
  for (; !q.empty();) {
    o = q.front();
    q.pop();
    ind[o] = 0;
    for (int i = head[o]; i; i = lk[i].nt) {
      int po = lk[i].p;
      if (visE[i]) continue;
      ind[po]--, visE[i] = visE[i ^ 1] = 1;
      if (ind[po] < k && !vis[po]) q.push(po), vis[po] = 1;
    }
  }
  for (int i = 1; i <= n; ++i)
    if (!vis[i] && !be[i]) ++nn, dfs(i);
  for (int i = 1; i <= nn; ++i) push(i);
  for (int i = cat; i >= 2; i -= 2) {
    ans[i / 2] = num[s[1]];
    if (visE[i]) continue;
    if (!vis[lk[i].fr] && !vis[lk[i].p]) {
      ind[lk[i].fr]--, ind[lk[i].p]--;
      visE[i] = visE[i ^ 1] = 1;
      if (ind[lk[i].fr] < k) upd(lk[i].fr);
      if (ind[lk[i].p] < k) upd(lk[i].p);
      for (; !q.empty();) {
        o = q.front();
        q.pop();
        ind[o] = 0;
        for (int j = head[o]; j; j = lk[j].nt) {
          int po = lk[j].p;
          if (visE[j]) continue;
          ind[po]--, visE[j] = visE[j ^ 1] = 1;
          if (ind[po] < k && !vis[po]) upd(po);
        }
      }
    }
  }
  for (int i = 1; i <= m; ++i) printf("%d\n", ans[i]);
  return 0;
}
